\choice
{ $S=\left\{ -5; \dfrac{1}{6}; - \dfrac{8}{15} \right\}$ }
   { $S=\left\{ 5; \dfrac{1}{6}; \dfrac{8}{15} \right\}$ }
     { \True $ S=\left\{ -5; \dfrac{1}{6}; \dfrac{8}{15} \right\}$ }
    { $S=\left\{ -5; - \dfrac{1}{6}; \dfrac{8}{15} \right\}$ }
\loigiai{
$\left(- x - 5\right) \left(6 x - 1\right) \left(15 x - 8\right)=0$\\
$- x - 5=0$ hoặc $6 x - 1=0$ hoặc $15 x - 8=0$\\
$ x=-5$ hoặc $ x=\dfrac{1}{6}$ hoặc $ x=\dfrac{8}{15}.$\\
$ S=\left\{ -5;  \dfrac{1}{6};  \dfrac{8}{15} \right\}$
}\end{ex}

